import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        char[][] board = new char[3][3];
        for (char[] row : board) java.util.Arrays.fill(row, '.');
        char player = 'X';

        while (true) {
            System.out.print(player + " to move: ");
            if (!in.hasNextLine()) {
                System.out.println("Game abandoned.");
                return;
            }
            String[] parts = in.nextLine().trim().split("\\s+");
            int row = 0, col = 0;
            boolean numbers = parts.length == 2;
            if (numbers) {
                try {
                    row = Integer.parseInt(parts[0]);
                    col = Integer.parseInt(parts[1]);
                } catch (NumberFormatException e) {
                    numbers = false;
                }
            }
            if (!numbers) {
                System.out.println("Enter row and column, like 2 3");
                continue;
            }
            if (row < 1 || row > 3 || col < 1 || col > 3) {
                System.out.println("Out of range");
                continue;
            }
            if (board[row - 1][col - 1] != '.') {
                System.out.println("Taken");
                continue;
            }
            board[row - 1][col - 1] = player;
            printBoard(board);
            if (winner(board) == player) {
                System.out.println(player + " wins!");
                return;
            }
            if (isFull(board)) {
                System.out.println("Draw.");
                return;
            }
            player = player == 'X' ? 'O' : 'X';
        }
    }

    static void printBoard(char[][] board) {
        for (int r = 0; r < 3; r++) {
            System.out.println(" " + board[r][0] + " | " + board[r][1] + " | " + board[r][2]);
            if (r < 2) System.out.println("---+---+---");
        }
    }

    static char winner(char[][] b) {
        for (int i = 0; i < 3; i++) {
            if (b[i][0] != '.' && b[i][0] == b[i][1] && b[i][1] == b[i][2]) return b[i][0];
            if (b[0][i] != '.' && b[0][i] == b[1][i] && b[1][i] == b[2][i]) return b[0][i];
        }
        if (b[1][1] != '.' && ((b[0][0] == b[1][1] && b[1][1] == b[2][2]) || (b[0][2] == b[1][1] && b[1][1] == b[2][0]))) {
            return b[1][1];
        }
        return '.';
    }

    static boolean isFull(char[][] board) {
        for (char[] row : board)
            for (char c : row)
                if (c == '.') return false;
        return true;
    }
}
